from __future__ import annotations

from agent.documents.credit_pdf.models import ParsedBureauReport, ParsedCreditReport, ParsedSummary


def reconcile_summaries(parsed: ParsedCreditReport) -> ParsedCreditReport:
    """Fill missing summary totals from tradeline aggregates per bureau."""
    for report in parsed.bureaus.values():
        _reconcile_bureau_summary(report)
    return parsed


def _reconcile_bureau_summary(report: ParsedBureauReport) -> None:
    if not report.tradelines:
        return

    summary = report.summary or ParsedSummary()
    total_balance = 0.0
    total_limit = 0.0
    revolving_balance = 0.0
    revolving_limit = 0.0
    open_count = 0
    late_30 = late_60 = late_90 = 0

    for tl in report.tradelines:
        balance = float(tl.balance or 0)
        limit = float(tl.credit_limit or 0)
        total_balance += balance
        if limit > 0:
            total_limit += limit
        acct_type = (tl.account_type or "").lower()
        if "revolv" in acct_type or "credit card" in acct_type or "bankcard" in acct_type:
            revolving_balance += balance
            if limit > 0:
                revolving_limit += limit
        if tl.is_open:
            open_count += 1
        late_30 += tl.late_30
        late_60 += tl.late_60
        late_90 += tl.late_90

    if summary.total_balance is None and total_balance > 0:
        summary.total_balance = total_balance
    if summary.total_credit_limit is None and total_limit > 0:
        summary.total_credit_limit = total_limit
    if summary.open_tradelines is None and open_count > 0:
        summary.open_tradelines = open_count
    if summary.total_tradelines is None:
        summary.total_tradelines = len(report.tradelines)
    if summary.revolving_utilization_pct is None and revolving_limit > 0:
        summary.revolving_utilization_pct = round(100.0 * revolving_balance / revolving_limit, 1)
    if summary.delinquencies_30 is None and late_30 > 0:
        summary.delinquencies_30 = late_30
    if summary.delinquencies_60 is None and late_60 > 0:
        summary.delinquencies_60 = late_60
    if summary.delinquencies_90 is None and late_90 > 0:
        summary.delinquencies_90 = late_90

    if summary.monthly_payment_total is None:
        monthly_from_tls = sum(float(tl.monthly_payment or 0) for tl in report.tradelines)
        if monthly_from_tls > 0:
            summary.monthly_payment_total = monthly_from_tls

    report.summary = summary
