def _summary_from_tradelines(tradelines: List[dict[str, Any]]) -> dict[str, Any]:
    total_balance = 0.0
    total_limit = 0.0
    revolving_balance = 0.0
    revolving_limit = 0.0
    bankcard_balance = 0.0
    bankcard_limit = 0.0
    hard_inquiries = 0
    open_count = 0
    late_30 = late_60 = late_90 = 0

    for tl in tradelines:
        balance = float(tl.get("balance") or 0)
        limit = float(tl.get("credit_limit") or 0)
        total_balance += balance
        if limit > 0:
            total_limit += limit
        acct_type = str(tl.get("account_type") or "").lower()
        if "revolv" in acct_type or tl.get("is_revolving"):
            revolving_balance += balance
            if limit > 0:
                revolving_limit += limit
        if "bankcard" in acct_type or "credit card" in acct_type:
            bankcard_balance += balance
            if limit > 0:
                bankcard_limit += limit
        if tl.get("is_open"):
            open_count += 1
        late_30 += int(tl.get("late_30") or 0)
        late_60 += int(tl.get("late_60") or 0)
        late_90 += int(tl.get("late_90") or 0)

    revolving_util = round((revolving_balance / revolving_limit) * 100, 1) if revolving_limit else None
    bankcard_util = round((bankcard_balance / bankcard_limit) * 100, 1) if bankcard_limit else None

    data_set = [
        {"@_Name": "Total Balance", "@_ID": "PT202", "@_Value": str(int(total_balance))},
        {"@_Name": "Total Credit Limit", "@_ID": "PT054", "@_Value": str(int(total_limit))},
        {"@_Name": "Revolving Utilization", "@_ID": "PT016", "@_Value": str(revolving_util or "")},
        {"@_Name": "Bankcard Utilization", "@_ID": "PT126", "@_Value": str(bankcard_util or "")},
        {"@_Name": "Hard Inquiries", "@_ID": "AP004", "@_Value": str(hard_inquiries)},
        {"@_Name": "Delinquencies 30", "@_ID": "AP008", "@_Value": str(late_30)},
        {"@_Name": "Delinquencies 60", "@_ID": "AP009", "@_Value": str(late_60)},
        {"@_Name": "Delinquencies 90", "@_ID": "AP010", "@_Value": str(late_90)},
        {"@_Name": "Open Tradelines", "@_ID": "PT201", "@_Value": str(open_count)},
    ]
    return {"@BorrowerID": "B1", "@_Name": "CreditSummary", "_DATA_SET": data_set}


def _build_summary_mismo(summary: Optional[ParsedSummary], tradelines: List[dict[str, Any]]) -> dict[str, Any]:
