def _build_liability(idx: int, tl: dict[str, Any], borrower_id: str) -> dict[str, Any]:
    liability_id = f"L{idx + 1}"
    creditor_name = str(tl.get("creditor") or tl.get("creditor_name") or "Unknown Creditor")
    balance = tl.get("balance")
    limit = tl.get("credit_limit")
    status = str(tl.get("status") or "Open")
    is_closed = "Y" if status.lower() in {"closed", "paid", "transferred"} or not tl.get("is_open", True) else "N"
    is_collection = "Y" if tl.get("is_collection") else "N"
    is_chargeoff = "Y" if tl.get("is_chargeoff") else "N"

    row: dict[str, Any] = {
        "@CreditLiabilityID": liability_id,
        "@BorrowerID": borrower_id,
        "@_AccountIdentifier": tl.get("account_number") or "",
        "@_AccountOpenedDate": tl.get("opened_date") or "",
        "@_AccountStatusType": status,
        "@_AccountType": tl.get("account_type") or "Revolving",
        "@_AccountOwnershipType": tl.get("account_ownership_type") or "",
        "@_CreditLimitAmount": str(limit or ""),
        "@_HighCreditAmount": str(tl.get("high_credit") or ""),
        "@_UnpaidBalanceAmount": str(balance or ""),
        "@_MonthlyPaymentAmount": str(tl.get("monthly_payment") or ""),
        "@_LastActivityDate": tl.get("last_activity_date") or "",
        "@_MonthsReviewedCount": str(tl.get("months_reviewed") or ""),
        "@_AccountReportedDate": tl.get("account_reported_date") or "",
        "@IsClosedIndicator": is_closed,
        "@IsCollectionIndicator": is_collection,
        "@IsChargeoffIndicator": is_chargeoff,
        "@_DerogatoryDataIndicator": "Y"
        if is_collection == "Y" or is_chargeoff == "Y" or tl.get("is_derogatory")
        else "N",
        "_CREDITOR": {
            "@_Name": creditor_name,
            "@_Phone": tl.get("creditor_phone") or "",
        },
        "_LATE_COUNT": {
            "@_30Days": str(tl.get("late_30") or 0),
            "@_60Days": str(tl.get("late_60") or 0),
            "@_90Days": str(tl.get("late_90") or 0),
        },
    }

    manner = tl.get("manner_of_payment") or ""
    rating_match = re.search(r"\(([A-Z]\d{2})\)", manner)
    if rating_match:
        row["_CURRENT_RATING"] = {"@_Code": rating_match.group(1), "@_Type": "AsAgreed"}

    comment = tl.get("comment_text") or ""
    if comment:
        row["CREDIT_COMMENT"] = {"@_Type": "Bureau", "_Text": comment}

    return row


