def is_report_supported(document_type: DocumentType) -> bool:
    if not settings.document_ingestion_enabled:
        return False
    return document_type not in REPORT_EXCLUDED_DOCUMENT_TYPES


def is_report_available(doc: UserDocument) -> bool:
    if not is_report_supported(doc.document_type):
        return False
    status = getattr(doc, "ingestion_status", IngestionStatus.NOT_QUEUED)
    if isinstance(status, str):
        try:
            status = IngestionStatus(status)
        except ValueError:
            status = IngestionStatus.NOT_QUEUED
    return status == IngestionStatus.READY


